layer.css:
@import url("https://fonts.googleapis.com/css?family=Google%20Sans%3A400");
@import url("https://fonts.googleapis.com/css?family=Google%20Sans%3A700");
[data-ryt="footer"] { color: color-mix(in srgb, var(--ryt-text) 87%, transparent); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="brand"] { color: rgb(204, 204, 204); border-radius: 0px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(204, 204, 204); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="header"] { box-shadow: color-mix(in srgb, var(--ryt-text) 15%, transparent) 0px 8px 16px 0px }
[data-ryt="button"] { color: var(--ryt-header-text); background-color: var(--ryt-header-bg); border-top: 1px solid var(--ryt-header-bg); border-right: 1px solid var(--ryt-header-bg); border-bottom: 1px solid var(--ryt-header-bg); border-left: 1px solid var(--ryt-header-bg); border-radius: 6px; font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 16px; padding-right: 12px; padding-bottom: 16px; padding-left: 12px; transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out, border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: color-mix(in srgb, var(--ryt-text) 87%, transparent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-text) 87%, transparent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: color-mix(in srgb, var(--ryt-text) 87%, transparent); font-family: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 40px; font-weight: 600; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-text) 87%, transparent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="button"]:hover { color: #fff; background-color: #5e38a4 }
[data-ryt="brand"]:hover { color: #fff; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
